%% Plots blob volumes, number, and surface area
% Takes in data generated by batchProcessSrtucturePower.m
% 2023/11/03 -
%% Data info
% dataDir = 'Session 56, Exp 1';
% dataDir = '<redacted original absolute path>';
dataDir = 'Session 45, Exp 3';
dataName = 'blobInfo_t%03i.mat';

timeRange = 1:100;

%% It
numObjs = zeros(1,numel(timeRange));
volStats = zeros(2,numel(timeRange));
surfStats = volStats;
maxintStats = volStats;
for tInd = 1:numel(timeRange)
    currT = timeRange(tInd);
    currName = fullfile(dataDir,sprintf(dataName,currT));
    if isfile(fullfile(dataDir,sprintf(dataName,currT)))
        load(currName);
    else
        continue
    end
    numObjs(tInd) = size(propStructBW,1);
    volStats(:,tInd) = [mean([propStructBW.Volume]); std([propStructBW.Volume])];
    surfStats(:,tInd) =[mean([propStructBW.SurfaceArea]); std([propStructBW.SurfaceArea])];
    maxintStats(:,tInd) =[mean([propStructBW.MaxIntensity]); std([propStructBW.MaxIntensity])];

end

